{
  "version": "v0.9.1",
  "createSurface": {
    "surfaceId": "water-cycle-lesson",
    "catalogId": "https://a2uicatalog.ai/catalog/c-learning.json"
  }
}
</a2ui-json>

<a2ui-json>
{
  "version": "v0.9.1",
  "updateComponents": {
    "surfaceId": "water-cycle-lesson",
    "components": [
      {
        "id": "root",
        "component": "page_header",
        "title": "Earth's Hydrological Cycle",
        "subtitle": "Discover the continuous movement of water on, above, and below the surface of the Earth.",
        "icon": "💧",
        "tag": "Earth Science",
        "accent": "#0284c7"
      },
      {
        "id": "reading-progress",
        "component": "reading_progress_bar",
        "color": "#0284c7"
      },
      {
        "id": "section-1-heading",
        "component": "heading",
        "text": "1. Evaporation & Transpiration"
      },
      {
        "id": "section-1-body",
        "component": "body",
        "text": "The cycle begins when solar radiation heats water bodies (oceans, lakes, rivers), causing liquid water to absorb thermal energy and transform into water vapor. Additionally, plants release water vapor into the air through their leaves in a biological process known as **transpiration**."
      },
      {
        "id": "section-1-callout",
        "component": "text_callout",
        "variant": "info",
        "title": "Did you know?",
        "description": "Around 90% of atmospheric water comes from evaporation, while the remaining 10% is primarily contributed by plant transpiration."
      },
      {
        "id": "section-2-heading",
        "component": "heading",
        "text": "2. Condensation & Cloud Formation"
      },
      {
        "id": "section-2-body",
        "component": "body",
        "text": "As water vapor rises higher into the troposphere, it cools down. When it reaches its dew point, the vapor condenses back into liquid droplets or ice crystals. These droplets cling to microscopic airborne particles (like dust or smoke) to form clouds and fog."
      },
      {
        "id": "section-3-heading",
        "component": "heading",
        "text": "3. Precipitation & Collection"
      },
      {
        "id": "section-3-body",
        "component": "body",
        "text": "When clouds become saturated, gravity pulls the accumulated moisture back to Earth. This falls as rain, snow, sleet, or hail. Once on land, water runs off into rivers and oceans, or infiltrates deep into the soil to replenish groundwater aquifers, resetting the cycle."
      },
      {
        "id": "worked-example-title",
        "component": "heading",
        "text": "Worked Example & Analysis"
      },
      {
        "id": "worked-example-case",
        "component": "case_study_card",
        "title": "Real-World Scenario: Watershed Dynamics",
        "situation": "A coastal metropolitan region experiences rapid concrete urbanization, covering previously exposed forest soils. During a heavy 3-inch rainfall event, the city's storm drainage system overflows, causing immediate flooding downriver rather than replenishing local wells.",
        "data_points": [
          {
            "label": "Precipitation Volume",
            "value": "3.0 inches",
            "note": "Dense thunderstorm system"
          },
          {
            "label": "Soil Infiltration Rate",
            "value": "-85%",
            "note": "Reduction due to concrete coverage"
          },
          {
            "label": "Surface Runoff Velocity",
            "value": "+300%",
            "note": "Exponentially faster pathing to sea level"
          }
        ],
        "questions": [
          "Which specific step of the water cycle was disrupted by the urban concrete infrastructure?",
          "Why did downriver flooding happen so rapidly compared to the natural forest state?"
        ],
        "model_answer": "The urban development disrupted soil infiltration and percolation. Because water could not sink into the ground to recharge the aquifer, gravity accelerated surface runoff across the slick asphalt surfaces directly into river channels, overwhelming local drainage capacities and precipitating rapid downstream floods.",
        "accent": "#0284c7"
      },
      {
        "id": "quiz-heading",
        "component": "heading",
        "text": "Interactive Self-Check Quiz"
      },
      {
        "id": "cycle-quiz",
        "component": "quiz_set",
        "title": "Test Your Hydrology Knowledge",
        "questions": [
          {
            "question": "What is the primary driving energy source that powers the global water cycle?",
            "options": [
              "Geothermal vents in the deep ocean",
              "Solar radiation from the Sun",
              "The gravitational pull of the Moon",
              "Wind currents generated by Earth's rotation"
            ],
            "correct": 1,
            "explanation": "Solar energy heats liquid water across the globe, driving evaporation, which acts as the physical engine for the entire cycle."
          },
          {
            "question": "Which term describes water vapor emitted directly from plant life into the atmosphere?",
            "options": [
              "Sublimation",
              "Infiltration",
              "Transpiration",
              "Condensation"
            ],
            "correct": 2,
            "explanation": "Transpiration is the biological release of water vapor through microscopic pores (stomata) on leaves."
          },
          {
            "question": "At what point does water vapor condense to form clouds?",
            "options": [
              "When it warms up near asphalt cities",
              "When it mixes with ocean salt spray",
              "When it cools to or below its dew point in the atmosphere",
              "When it encounters low gravitational zones"
            ],
            "correct": 3,
            "explanation": "Cooling is essential for condensation; as warm vapor rises and cools down to its dew point temperature, it transitions back to a liquid state around tiny particulate nuclei."
          }
        ],
        "pass_score": 66,
        "accent": "#0284c7"
      }
    ]
  }
}
